-- Debt ledger notifications are generated by a database trigger.
-- Include their type in the notification constraint so ledger writes remain atomic.
ALTER TABLE public.user_notifications
  DROP CONSTRAINT user_notifications_type_check;
ALTER TABLE public.user_notifications
  ADD CONSTRAINT user_notifications_type_check
  CHECK (type = ANY (ARRAY['order','cashback','loyalty','payment','system','debt']::text[]));

ALTER FUNCTION public.notify_workshop_debt_ledger()
  SET search_path = pg_catalog, public;
REVOKE ALL ON FUNCTION public.notify_workshop_debt_ledger() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.notify_workshop_debt_ledger() TO service_role;
